export default async function step({ events, ack, resolution, confirmedJobId }, ctx) {
  if (!Array.isArray(events) || !events.length) throw Error("No changed documents");
  const identity = JSON.stringify(events.map((x) => [x.fileId, x.modifiedTime]));
  let hash = 2166136261;
  for (const c of identity) hash = Math.imul(hash ^ c.charCodeAt(0), 16777619);
  const key = "radar-doc:" + String(hash >>> 0);
  let s = await ctx.state.get(key);
  if (!s) s = { identity, index: 0, offset: 0, polls: 0, phase: "read-ready" };
  if (s.identity !== identity) throw Error("Batch hash conflict");
  if (s.phase === "read-pending") {
    if (ack !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending relay upload " + key);
    if (resolution === "absent") s.phase = "read-ready";
    else {
      if (!/^[A-Za-z0-9_-]+$/.test(confirmedJobId)) throw Error("Enter confirmed parse job ID");
      s.jobId = confirmedJobId;
      s.polls = 0;
      s.phase = "poll-ready";
    }
    await ctx.state.set(key, s);
  }
  if (s.phase === "upsert-pending") {
    if (ack !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending vector write " + key);
    if (resolution === "confirmed") {
      if (s.offset + 1024 >= s.text.length) {
        s.index++;
        s.offset = 0;
        delete s.text;
      } else s.offset += 924;
      s.phase = s.index < events.length ? (s.text ? "embed-ready" : "read-ready") : "done";
    } else s.phase = "embed-ready";
    await ctx.state.set(key, s);
  }
  let action = s.phase.endsWith("-ready") ? s.phase.slice(0, -6) : s.phase,
    e = events[s.index];
  if (e && (!e.fileId || !e.mimeType || !e.modifiedTime)) throw Error("Unexpected document event");
  if (action === "read") s.phase = "read-pending";
  await ctx.state.set(key, s);
  let text = s.text?.slice(s.offset, s.offset + 1024) || " ";
  return {
    key,
    action,
    jobId: s.jobId ?? "none",
    fileId: e?.fileId ?? "",
    name: e?.name ?? "",
    modified: e?.modifiedTime ?? "",
    offset: s.offset,
    text,
    request: {
      fileId: e?.fileId ?? "",
      name: e?.name ?? "",
      mimeType: e?.mimeType ?? "",
      modifiedTime: e?.modifiedTime ?? "",
    },
  };
}

