export default async function confirm({ key, fileId, status, body }, ctx) {
  let s = await ctx.state.get(key);
  if (!s || s.phase !== "read-pending" || status !== 200 || body?.fileId !== fileId)
    throw Error("Invalid document relay");
  if (typeof body.text === "string" && body.text.trim()) {
    s.text = body.text;
    s.phase = "embed-ready";
  } else if (typeof body.jobId === "string" && /^[A-Za-z0-9_-]+$/.test(body.jobId)) {
    s.jobId = body.jobId;
    s.polls = 0;
    s.phase = "poll-ready";
  } else throw Error("Missing text or parse job");
  await ctx.state.set(key, s);
  return { ok: true };
}

