export default async function poll({ key, jobId, status, body }, ctx) {
  let s = await ctx.state.get(key);
  if (!s || s.phase !== "poll-ready" || s.jobId !== jobId || status !== 200 || body?.id !== jobId)
    throw Error("Invalid parse status");
  if (body.status === "SUCCESS") s.phase = "markdown-ready";
  else if (["PENDING", "RUNNING"].includes(body.status)) {
    if (++s.polls > 240) throw Error("Parse timed out");
  } else throw Error("Parse failed or incomplete");
  await ctx.state.set(key, s);
  return { ok: true };
}

