export default async function markdown({ key, jobId, status, body }, ctx) {
  let s = await ctx.state.get(key);
  if (
    !s ||
    s.phase !== "markdown-ready" ||
    s.jobId !== jobId ||
    status !== 200 ||
    typeof body?.markdown !== "string" ||
    !body.markdown.trim()
  )
    throw Error("Invalid parsed text");
  s.text = body.markdown;
  s.phase = "embed-ready";
  delete s.jobId;
  await ctx.state.set(key, s);
  return { ok: true };
}

