export default async function vector(
  { key, fileId, name, modified, offset, text, embedding },
  ctx,
) {
  let s = await ctx.state.get(key);
  if (
    !s ||
    s.phase !== "embed-ready" ||
    s.offset !== offset ||
    !text ||
    !Array.isArray(embedding) ||
    embedding.length !== 3072
  )
    throw Error("Invalid document embedding");
  s.phase = "upsert-pending";
  await ctx.state.set(key, s);
  return {
    vectors: [
      {
        id: fileId + ":" + modified + ":" + offset,
        values: embedding,
        metadata: { fileId, name, modified, text },
      },
    ],
  };
}

