export default async function confirm({ key, count }, ctx) {
  let s = await ctx.state.get(key);
  if (!s || s.phase !== "upsert-pending" || count !== 1) throw Error("Inspect Pinecone write");
  if (s.offset + 1024 >= s.text.length) {
    s.index++;
    s.offset = 0;
    delete s.text;
  } else s.offset += 924;
  let events = JSON.parse(s.identity);
  s.phase = s.index < events.length ? (s.text ? "embed-ready" : "read-ready") : "done";
  await ctx.state.set(key, s);
  return { ok: true };
}
